package br.com.tapeteskalke.service; import br.com.tapeteskalke.dto.AuthDtos.*; import br.com.tapeteskalke.entity.Usuario; import br.com.tapeteskalke.exception.BusinessException; import br.com.tapeteskalke.repository.UsuarioRepository; import br.com.tapeteskalke.security.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UsuarioRepository users; private final PasswordEncoder encoder; private final JwtTokenService tokens; private final PermissionService permissions; private final LoginAttemptService attempts; public AuthService(UsuarioRepository users,PasswordEncoder encoder,JwtTokenService tokens,PermissionService permissions,LoginAttemptService attempts){this.users=users;this.encoder=encoder;this.tokens=tokens;this.permissions=permissions;this.attempts=attempts;} @Transactional(readOnly=true) public LoginResponse login(LoginRequest r,String ip){var email=r.email().trim();attempts.checkAllowed(email,ip);var user=users.findByEmailIgnoreCaseAndAtivoTrue(email).orElse(null);if(user==null||!encoder.matches(r.senha(),user.getSenhaHash())){attempts.failed(email,ip);throw invalid();}attempts.succeeded(email,ip);return loginResponse(user);} @Transactional public void logout(UserPrincipal p){users.revokeSessions(p.id());} @Transactional(readOnly=true) public UserResponse me(UserPrincipal p){var nome=users.findById(p.id()).map(Usuario::getNome).orElse(p.email());return new UserResponse(p.id(),nome,p.email(),p.role(),permissions.pagesFor(p.role()),permissions.actionsFor(p.role()));} private LoginResponse loginResponse(Usuario u){var role=u.getCargo().getCodigo();var user=new UserResponse(u.getId(),u.getNome(),u.getEmail(),role,permissions.pagesFor(role),permissions.actionsFor(role));return new LoginResponse(tokens.issue(u.getId(),u.getEmail(),role,u.getSessaoVersao()),tokens.expirationSeconds(),user);} private BusinessException invalid(){return new BusinessException("CREDENCIAIS_INVALIDAS","E-mail ou senha inválidos",HttpStatus.UNAUTHORIZED);} }
